// expect: exit 120
// screen: 0 -----
// screen: 1 5! = 120
void dashes(int n)
{
    while (n--)
        putchar('-');
    puts("");
}
int fact(int n)
{
    if (n <= 1)
        return 1;
    return n * fact(n - 1);
}
int main(void)
{
    cls();
    dashes(5);
    printf("5! = %d\n", fact(5));
    return fact(5);
}
